import { describe, expect, it, vi } from "vitest";
import type { ProjectDefinition } from "../../src/contract/v5";
import { createManualClock } from "../../src/ports/clock";
import { INLINE_JOB_MESSAGE, deferredScheduler, type Cancel } from "../../src/ports/scheduler";
import { GraphRuntime } from "../../src/runtime/graph-runtime";

/**
 * Issue #377, found by the quality pass over #375.
 *
 * The `Scheduler` port declared `schedule(job, options?): Cancel` and said nothing about when the
 * job runs, so a port that ran its job inline satisfied the contract while breaking the runtime.
 * `#scheduleDrain` books from inside the publication that deferred, the job lowers that booking as
 * its first act, and a `flush` from inside the same publication defers and books again. That is
 * unbounded recursion to a stack overflow rather than a slow drain, and the booking cannot stop it
 * because it is lowered before `schedule` has returned.
 *
 * ADR-038 already decided the pass boundary for the shipped adapter, so nothing reachable today
 * recursed. #377 is that the decision lived in a record and in this runtime's assumptions and not
 * in the contract a future adapter reads. It is decided at the port, which is the issue's own first
 * recommendation, and enforced there once instead of guarded at every call site. See ADR-086.
 */

const project: ProjectDefinition = {
  schemaVersion: 5,
  motions: [
    { id: "hero", trigger: { type: "manual" }, tracks: [{ id: "arm" }] },
    { id: "caption", trigger: { type: "manual" }, tracks: [{ id: "label" }] },
  ],
};

const compose = (node: { id: string }) => () => ({
  values: { node: node.id },
  sourceProgress: 0,
  sourceRevisions: {},
});

describe("a Scheduler defers, and the port is what says so", () => {
  it("passes a job through to a port that defers, and hands back that port's own handle", () => {
    const jobs: (() => void)[] = [];
    const cancel = vi.fn();
    const guarded = deferredScheduler({
      schedule(job: () => void): Cancel {
        jobs.push(job);
        return { cancel };
      },
    });

    let ran = 0;
    const handle = guarded.schedule(() => (ran += 1));

    expect(jobs).toHaveLength(1);
    expect(ran).toBe(0);
    jobs[0]?.();
    expect(ran).toBe(1);
    handle.cancel();
    expect(cancel).toHaveBeenCalledTimes(1);
  });

  it("refuses a job the port runs before schedule returns, rather than running it", () => {
    let ran = 0;
    const guarded = deferredScheduler({
      schedule(job: () => void): Cancel {
        job();
        return { cancel() {} };
      },
    });

    // Running the job is the recursion, so refusing to run it is the fix rather than a symptom of
    // one. The refusal leaves through `schedule`, which every caller already has a boundary for.
    expect(() => guarded.schedule(() => (ran += 1))).toThrow(INLINE_JOB_MESSAGE);
    expect(ran).toBe(0);
  });

  it("refuses every later call once a port has run one job inline", () => {
    let attempts = 0;
    const guarded = deferredScheduler({
      schedule(job: () => void): Cancel {
        attempts += 1;
        try {
          job();
        } catch {
          // A port that swallows the refusal must not buy a second inline pass with it.
        }
        return { cancel() {} };
      },
    });

    expect(() => guarded.schedule(() => undefined)).not.toThrow();
    expect(() => guarded.schedule(() => undefined)).toThrow(INLINE_JOB_MESSAGE);
    expect(attempts).toBe(1);
  });

  it("bounds a runtime composed over a synchronous port, and keeps that runtime's work", () => {
    const clock = createManualClock();
    let calls = 0;
    const runtime = new GraphRuntime(project, clock, compose, {
      scheduler: {
        schedule(job: () => void): Cancel {
          calls += 1;
          job();
          return { cancel() {} };
        },
      },
    });
    runtime.attach("hero/arm");

    let acted = false;
    runtime.registry.subscribeNode("hero/arm", () => {
      if (acted) return;
      acted = true;
      runtime.flush(["caption/label"]);
    });

    // Red before the port was enforced: this recursed until the stack ran out.
    expect(() => clock.tick()).not.toThrow();
    expect(calls).toBeLessThanOrEqual(2);
    expect(runtime.lastFlushError?.ruleId).toBe("scheduler-failure");
    expect(runtime.lastFlushError?.message).toMatch(/before schedule\(\) returns/);

    // The work is not dropped. It stays pending and the next publication carries it, which is
    // exactly what a runtime given no scheduler at all already does.
    expect(runtime.pendingSeeds).toEqual(["caption/label"]);
    runtime.flush([]);
    expect(runtime.pendingSeeds).toEqual([]);
    expect(runtime.registry.get("caption/label")?.values.node).toBe("caption/label");
    runtime.dispose();
  });
});

import { describe, expect, it } from "vitest";
import type { ProjectDefinition } from "../../../src/contract/v5";
import { createManualClock } from "../../../src/ports/clock";
import { createFakeScheduler } from "../../../src/testing/fakes";
import { GraphRuntime } from "../../../src/runtime/graph-runtime";

/**
 * Issue #378, found by the quality pass over #375.
 *
 * `#flushSeeds` drained the pending payload and derived the publisher snapshot before the boundary
 * that re-queues it. Derivation is not runtime bookkeeping: on a cold memo it builds publisher
 * nodes, and building one calls the constructor-supplied `compose` and `interpolated` suppliers. So
 * caller code ran between the drain and the `catch` written to preserve that work, and a supplier
 * that threw dropped every seed the call had just taken. From the clock path the loss was quiet,
 * because the next tick re-seeds from the member set; from a direct `flush(seeds)` it was silent
 * and total.
 *
 * The ordering predates the split, so #375 did not introduce it; extracting the three statements
 * into one owner is what made the missing boundary legible. The docblock claimed more than the code
 * delivered, and that is the part worth pinning: a publisher failure re-queued and a snapshot
 * failure did not, and a reader had no reason to expect the distinction. See ADR-086.
 */

const project: ProjectDefinition = {
  schemaVersion: 5,
  motions: [
    { id: "hero", trigger: { type: "manual" }, tracks: [{ id: "arm" }] },
    { id: "caption", trigger: { type: "manual" }, tracks: [{ id: "label" }] },
  ],
};

describe("the publication boundary covers everything after the drain", () => {
  it("keeps the drained seeds when the injected compose supplier throws", () => {
    const clock = createManualClock();
    const scheduler = createFakeScheduler();
    const failure = new Error("compose refused");
    let refusing = false;
    const compose = (node: { id: string }) => {
      if (refusing) throw failure;
      return () => ({ values: { node: node.id }, sourceProgress: 0, sourceRevisions: {} });
    };
    const runtime = new GraphRuntime(project, clock, compose, { scheduler });
    runtime.attach("hero/arm");

    let acted = false;
    runtime.registry.subscribeNode("hero/arm", () => {
      if (acted) return;
      acted = true;
      runtime.flush(["caption/label"]);
    });

    clock.tick();
    expect(runtime.pendingSeeds).toEqual(["caption/label"]);

    // `replaceGraph` colds the memo and releases the cached publisher nodes, which is what puts the
    // injected supplier back on the publication path. Nothing else here needs the graph to move.
    runtime.replaceGraph(project);
    refusing = true;

    // Red before this change: the pending seed was taken and cleared before the boundary that
    // restores it, so the `catch` never saw it and a direct caller lost the work outright.
    expect(() => runtime.flush(["hero/arm"])).toThrow(failure);
    expect([...runtime.pendingSeeds].sort()).toEqual(["caption/label", "hero/arm"]);

    // Deferred rather than dropped, which is what the docblock always claimed: the follow-up the
    // failed publication booked publishes both seeds once the supplier answers again.
    refusing = false;
    scheduler.flush();
    expect(runtime.pendingSeeds).toEqual([]);
    expect(runtime.registry.get("hero/arm")?.values.node).toBe("hero/arm");
    expect(runtime.registry.get("caption/label")?.values.node).toBe("caption/label");
    runtime.dispose();
  });
});

import { describe, expect, it } from "vitest";
import type { Diagnostic, ProjectDefinition } from "../../../src/contract/v5";
import { createManualClock } from "../../../src/ports/clock";
import { createFakeScheduler } from "../../../src/testing/fakes";
import { GraphRuntime } from "../../../src/runtime/graph-runtime";
import type { PatchBatch } from "../../../src/runtime/patch-registry";

/**
 * Issue #383, found by the quality pass over #375.
 *
 * The message under `reentrant-flush-deferred` said the flush "was queued as one follow-up
 * invalidation for the scheduler", and two of its words were wrong. `invalidate` is an operation
 * ADR-082 retired from this tier, so a reader tracing the diagnostic looked for a member that is
 * not there. And "for the scheduler" presumed one: `#scheduleDrain` answers immediately when there
 * is none, the seeds wait for whatever flush runs next, and `publisher-reentrancy` builds exactly
 * that runtime, so the wrong half was the half most of the existing evidence exercised.
 *
 * The rule id is accurate and does not move. Which of the two things happened is decided where it
 * is known, which is the one member that books. See ADR-086.
 */

const project: ProjectDefinition = {
  schemaVersion: 5,
  motions: [
    { id: "hero", trigger: { type: "manual" }, tracks: [{ id: "arm" }] },
    { id: "caption", trigger: { type: "manual" }, tracks: [{ id: "label" }] },
  ],
};

const compose = (node: { id: string }) => () => ({
  values: { node: node.id },
  sourceProgress: 0,
  sourceRevisions: {},
});

/** Drives one reentrant deferral and answers the diagnostic its batch carried. */
function deferralFrom(runtime: GraphRuntime, clock: { tick(): void }): Diagnostic {
  let deferred: PatchBatch | undefined;
  let acted = false;
  runtime.registry.subscribeNode("hero/arm", () => {
    if (acted) return;
    acted = true;
    deferred = runtime.flush(["caption/label"]);
  });
  clock.tick();
  const carried = deferred?.diagnostics.find(
    (entry) => entry.ruleId === "reentrant-flush-deferred",
  );
  if (carried === undefined) throw new Error("the deferral carried no diagnostic");
  return carried;
}

describe("the deferred-flush diagnostic says what actually happens to the work", () => {
  it("names a scheduled drain when a scheduler took the work", () => {
    const clock = createManualClock();
    const scheduler = createFakeScheduler();
    const runtime = new GraphRuntime(project, clock, compose, { scheduler });
    runtime.attach("hero/arm");

    const carried = deferralFrom(runtime, clock);

    expect(carried.message).toMatch(/scheduled drain/);
    expect(scheduler.pending).toHaveLength(1);
    runtime.dispose();
  });

  it("names the next flush when there is no scheduler to take it", () => {
    const clock = createManualClock();
    const runtime = new GraphRuntime(project, clock, compose);
    runtime.attach("hero/arm");

    const carried = deferralFrom(runtime, clock);

    // Red before this change: this runtime was told about a scheduler it was never given, and the
    // seeds are in fact carried by whatever flush runs next, which is the clock here.
    expect(carried.message).toMatch(/next flush/);
    expect(carried.message).not.toMatch(/scheduler/);
    expect(runtime.pendingSeeds).toEqual(["caption/label"]);
    clock.tick();
    expect(runtime.pendingSeeds).toEqual([]);
    runtime.dispose();
  });

  it("names no operation this tier retired, on either side", () => {
    const bookedClock = createManualClock();
    const scheduler = createFakeScheduler();
    const booked = new GraphRuntime(project, bookedClock, compose, { scheduler });
    booked.attach("hero/arm");
    const first = deferralFrom(booked, bookedClock);

    const carriedClock = createManualClock();
    const carrying = new GraphRuntime(project, carriedClock, compose);
    carrying.attach("hero/arm");
    const second = deferralFrom(carrying, carriedClock);

    // This tier's verb is `flush`; `invalidate` belongs to `ProjectRuntime` one layer up, so a
    // reader tracing either message reaches a member that exists. Rule id, severity and path are
    // untouched on both sides, which is what keeps this a message change and not a rule change.
    for (const carried of [first, second]) {
      expect(carried.message).not.toMatch(/invalidat/i);
      expect(carried.ruleId).toBe("reentrant-flush-deferred");
      expect(carried.severity).toBe("warning");
      expect(carried.path).toBe("deferred-flush");
    }
    booked.dispose();
    carrying.dispose();
  });
});
